def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # --- feature extraction ---
    opp_c = 0
    my_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
        if history[i][0] == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    last_me, last_opp = history[-1]

    # tail streak of opponent defections
    streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        i -= 1
    streak_c = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        streak_c += 1
        i -= 1

    # recency-weighted cooperation rate
    wsum = 0.0
    wcoop = 0.0
    for i in range(n):
        w = 1.0 + (i / max(1, n - 1)) * 3.0
        wsum += w
        if history[i][1] == 'C':
            wcoop += w
    rec_coop = wcoop / wsum if wsum > 0 else 0.5

    # look at last 10
    tail = history[-10:] if n >= 10 else history
    tail_len = len(tail)
    tail_c = 0
    for k in range(tail_len):
        if tail[k][1] == 'C':
            tail_c += 1
    tail_d = tail_len - tail_c

    remaining = 100 - n

    # --- endgame: strong defection against exploitable cooperators ---
    if remaining <= 3:
        if rec_coop > 0.45:
            return 'D'
        return 'C' if last_opp == 'C' else 'D'

    if remaining <= 7:
        # if opponent is mostly cooperative, exploit
        if opp_d <= max(2, n // 8):
            return 'D'
        if rec_coop > 0.55:
            return 'D'
        if streak_d >= 2:
            return 'D'
        return 'C'

    if remaining <= 14:
        if tail_d >= 6 and tail_len >= 8:
            return 'D'
        if opp_d <= max(3, n // 10):
            return 'D'
        if rec_coop > 0.65:
            return 'D'
        if streak_d >= 3:
            return 'D'
        if last_opp == 'C' and streak_c >= 2:
            return 'C'
        return 'C' if rec_coop > 0.35 else 'D'

    # --- opponent always defects very early ---
    if n >= 6 and opp_c == 0:
        return 'D'

    # --- opponent nearly always cooperates: exploit steadily ---
    if n >= 12 and opp_d <= 1:
        # probe occasionally then defect more later
        if n < 25:
            return 'D' if (n % 5 == 0 and rng.random() < 0.4) else 'C'
        if n >= 40:
            return 'D'
        return 'C'

    if n >= 8 and opp_d <= max(1, n // 10):
        # mostly cooperate, occasional exploit
        if n > 20 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # --- locked defection war: try to break out but be cautious ---
    if streak_d >= 4:
        # if opponent had cooperated substantially earlier, attempt reconciliation
        if opp_c >= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if streak_d == 3:
        return 'D'

    if streak_d == 2:
        # two-in-a-row: usually punish once more, sometimes forgive
        if opp_c * 2 >= n and rng.random() < 0.2:
            return 'C'
        return 'D'

    if streak_d == 1:
        # single defection: retaliate with decent probability, forgive otherwise
        if rec_coop > 0.55 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # --- opponent just cooperated ---
    if last_opp == 'C':
        # if opponent has a history of defection, be careful
        if opp_d * 2 > n:
            # previously defecting though now cooperative: punish sometimes
            if rng.random() < 0.6:
                return 'D'
            return 'C'
        # groom cooperative opponents; avoid probing when cooperation is healthy
        if rec_coop >= 0.85 and opp_d <= 2 and n > 15:
            # hard committed cooperator; exploit more aggressively later
            if remaining <= 25 and rng.random() < 0.3:
                return 'D'
        # periodic probe
        if n > 25 and rec_coop > 0.5 and rng.random() < 0.04:
            return 'D'
        return 'C'

    return 'C'
